def student_q(z, df):
    v = max(1, df)
    if v <= 60:
        for k, row in TABLE.items():
            if abs(k - z) < 1e-6:
                return row[v - 1]
    z3, z5, z7 = z ** 3, z ** 5, z ** 7
    return z + (z3 + z) / (4 * v) + (5 * z5 + 16 * z3 + 3 * z) / (96 * v * v) + (3 * z7 + 19 * z5 + 17 * z3 - 15 * z) / (384 * v ** 3)
